using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Collections.Generic;
using System.Net;
using System.Net.Http;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;
namespace Nexus {
  public static class SelfUpdaterTests {
    static int count;static void Check(bool value,string label){if(!value)throw new Exception("Self update: "+label);count++;}
    static void Reject(Action action,string label){try{action();}catch{count++;return;}throw new Exception("Self update expected rejection: "+label);}
    static string Payload(string version,string digest,bool beta,string name){return new JavaScriptSerializer().Serialize(new{tag_name=version,html_url="https://github.com/teasergames/ports-pc/releases/tag/"+version,draft=false,prerelease=beta,assets=new[]{new{name=name,size=100,browser_download_url="https://github.com/teasergames/ports-pc/releases/download/"+version+"/"+name,digest=digest}}});}
    static string Json(string version){return Payload(version,"sha256:"+new string('a',64),false,"Nexus-Ports-PC-"+version+"-Windows-x64.zip");}
    static string Package(string root,Dictionary<string,byte[]> files){string zip=Path.Combine(root,Guid.NewGuid().ToString("N")+".zip");using(var z=ZipFile.Open(zip,ZipArchiveMode.Create))foreach(var f in files)using(var s=z.CreateEntry(f.Key).Open())s.Write(f.Value,0,f.Value.Length);return zip;}
    public static int Run(string root){
      count=0;SelfUpdater.TestJobsRoot=Path.Combine(root,"launcher-update-tests");try{
        Check(Store.Parse("{\"Version\":1,\"Games\":[]}").AutoUpdateLauncher,"existing libraries default to auto update");var lib=new Library{AutoUpdateLauncher=false};Check(!Store.Parse(new JavaScriptSerializer().Serialize(lib)).AutoUpdateLauncher,"auto update opt out persists");
        string stable="v"+SelfUpdater.CurrentVersion;var release=SelfUpdater.Parse(Json(stable));Check(release.Version==stable&&SelfUpdater.StableVersion("v1.10.0")>SelfUpdater.StableVersion("v1.9.9"),"stable version comparison is numeric");
        Reject(()=>SelfUpdater.Parse(Payload(stable,null,false,release.AssetName)),"missing hash");Reject(()=>SelfUpdater.Parse(Payload(stable,"sha256:bad",false,release.AssetName)),"invalid hash");Reject(()=>SelfUpdater.Parse(Payload(stable,release.Digest,true,release.AssetName)),"beta release");Reject(()=>SelfUpdater.Parse(Json(stable).Replace("teasergames/ports-pc/releases/download","other/repository/releases/download")),"foreign owner");Reject(()=>SelfUpdater.Parse(Json(stable).Replace("Windows-x64","Windows-arm64")),"ARM64 package");Reject(()=>SelfUpdater.Parse(Json(stable).Replace("\"size\":100","\"size\":104857601")),"oversize ZIP");Reject(()=>SelfUpdater.StableVersion("v2.0.0-beta.1"),"prerelease tag");Reject(()=>SelfUpdater.Parse(Payload(stable,release.Digest,false,"Nexus-Ports-PC-v99.0.0-Windows-x64.zip")),"asset version mismatch");
        using(var updater=new SelfUpdater(new Reply(Json("v1.0.0"))))Check(updater.Check(CancellationToken.None).GetAwaiter().GetResult()==null,"never downgrade");using(var updater=new SelfUpdater(new Reply(Json(stable))))Check(updater.Check(CancellationToken.None).GetAwaiter().GetResult()==null,"equal version skipped");using(var updater=new SelfUpdater(new Reply(Json("v99.0.0"))))Check(updater.Check(CancellationToken.None).GetAwaiter().GetResult().Version=="v99.0.0","newer release detected");
        using(var updater=new SelfUpdater(new Reply(Json(stable)))){var canceled=new CancellationTokenSource();canceled.Cancel();Reject(()=>updater.Check(canceled.Token).GetAwaiter().GetResult(),"cancel check");}
        string manifest="{\"tag_name\":\"v99.0.0\",\"asset\":\"Nexus-Ports-PC-v99.0.0-Windows-x64.zip\",\"size\":100,\"digest\":\"sha256:"+new string('a',64)+"\",\"linux_asset\":\"Nexus-Ports-PC-v99.0.0-Linux-x86_64.AppImage\",\"linux_size\":200,\"linux_digest\":\"sha256:"+new string('b',64)+"\"}";
        using(var updater=new SelfUpdater(new RateLimited(manifest))){var found=updater.Check(CancellationToken.None).GetAwaiter().GetResult();Check(found!=null&&found.Version=="v99.0.0"&&found.DownloadUrl=="https://github.com/teasergames/ports-pc/releases/download/v99.0.0/Nexus-Ports-PC-v99.0.0-Windows-x64.zip","rate-limited API falls back to the release manifest");}
        using(var updater=new SelfUpdater(new RateLimited(null))){try{updater.Check(CancellationToken.None).GetAwaiter().GetResult();throw new Exception("FAIL: rate limit without manifest must fail");}catch(HttpRequestException ex){Check(ex.Message.Contains("Tente novamente"),"rate limit without manifest explains the retry");}}
        Reject(()=>SelfUpdater.FromManifest(manifest.Replace("v99.0.0-Windows","v98.0.0-Windows")),"manifest asset must match its version");Reject(()=>SelfUpdater.FromManifest(manifest.Replace("sha256:","md5:")),"manifest requires SHA-256");Reject(()=>SelfUpdater.FromManifest(manifest.Replace("v99.0.0\",","v99.0.0-beta\",")),"manifest rejects pre-release tags");
        string install=Path.Combine(root,"launcher & João's folder");Directory.CreateDirectory(install);string target=Path.Combine(install,"Nexus.exe");File.Copy(SelfUpdater.CurrentExe,target);File.WriteAllText(Path.Combine(install,"README.md"),"old docs");File.WriteAllText(Path.Combine(install,"library.json"),"personal library");Directory.CreateDirectory(Path.Combine(install,"ports"));File.WriteAllText(Path.Combine(install,"ports","game.dat"),"own game");
        var files=SelfUpdater.PackageFiles.ToDictionary(n=>n,n=>n=="Nexus.exe"?File.ReadAllBytes(SelfUpdater.CurrentExe):System.Text.Encoding.UTF8.GetBytes(n=="Nexus.exe.config"?"<configuration/>":"new "+n));string zip=Package(root,files);release.Digest="sha256:"+UpdateManager.Hash(zip);release.Size=new FileInfo(zip).Length;
        string job=SelfUpdater.NewJob(),planFile=SelfUpdater.Prepare(zip,release,job,target,root,CancellationToken.None);var plan=SelfUpdater.Read(planFile);Check(plan.State=="prepared"&&File.ReadAllText(Path.Combine(install,"README.md"))=="old docs","staging leaves installed files untouched");
        Reject(()=>SelfUpdater.Apply(job,plan,delegate(int at){if(at==2)throw new IOException("simulated interruption");}),"interrupted replacement");SelfUpdater.Rollback(job,plan);Check(File.ReadAllText(Path.Combine(install,"README.md"))=="old docs"&&!File.Exists(Path.Combine(install,"LICENSE"))&&plan.State=="rolledback","rollback restores originals and removes only newly installed application files");Check(File.ReadAllText(Path.Combine(install,"library.json"))=="personal library"&&File.ReadAllText(Path.Combine(install,"ports","game.dat"))=="own game","library and game content preserved");
        job=SelfUpdater.NewJob();planFile=SelfUpdater.Prepare(zip,release,job,target,root,CancellationToken.None);plan=SelfUpdater.Read(planFile);SelfUpdater.Apply(job,plan,null);Check(plan.State=="launching"&&SelfUpdater.PackageFiles.All(n=>UpdateManager.Hash(Path.Combine(install,n))==plan.Files[n]),"all program files committed");File.WriteAllText(Path.Combine(install,"README.md"),"external edit");Reject(()=>SelfUpdater.Rollback(job,plan),"rollback refuses external edits");File.WriteAllText(Path.Combine(install,"README.md"),"new README.md");SelfUpdater.Rollback(job,plan);
        job=SelfUpdater.NewJob();planFile=SelfUpdater.Prepare(zip,release,job,target,root,CancellationToken.None);plan=SelfUpdater.Read(planFile);File.WriteAllText(Path.Combine(job,"payload","LICENSE"),"tamper");Reject(()=>SelfUpdater.Apply(job,plan,null),"staged tampering");Check(plan.State=="prepared"&&File.ReadAllText(Path.Combine(install,"README.md"))=="old docs","tampered payload never commits");
        release.Digest="sha256:"+new string('0',64);Reject(()=>SelfUpdater.Prepare(zip,release,SelfUpdater.NewJob(),target,root,CancellationToken.None),"checksum mismatch");release.Digest=null;Reject(()=>SelfUpdater.Prepare(zip,release,SelfUpdater.NewJob(),target,root,CancellationToken.None),"staging cannot bypass mandatory digest");
        foreach(string bad in new[]{"../escape.exe","Nexus/library.json","extra.exe"}){var invalid=new Dictionary<string,byte[]>(files);invalid[bad]=new byte[]{1};string badZip=Package(root,invalid);release.Digest="sha256:"+UpdateManager.Hash(badZip);Reject(()=>SelfUpdater.Prepare(badZip,release,SelfUpdater.NewJob(),target,root,CancellationToken.None),"unexpected ZIP member "+bad);}
        var missing=new Dictionary<string,byte[]>(files);missing.Remove("LICENSE");string incomplete=Package(root,missing);release.Digest="sha256:"+UpdateManager.Hash(incomplete);Reject(()=>SelfUpdater.Prepare(incomplete,release,SelfUpdater.NewJob(),target,root,CancellationToken.None),"incomplete release");
        release.Digest="sha256:"+UpdateManager.Hash(zip);release.Version="v99.0.0";Reject(()=>SelfUpdater.Prepare(zip,release,SelfUpdater.NewJob(),target,root,CancellationToken.None),"PE assembly version mismatch");Reject(()=>SelfUpdater.ValidateJob(root),"arbitrary job folder");
        var download=SelfUpdater.Parse(Json("v99.0.0"));using(var updater=new SelfUpdater(new BinaryReply(new byte[]{1,2},null)))Reject(()=>updater.Download(download,root,null,CancellationToken.None).GetAwaiter().GetResult(),"truncated response rejected before staging");download.Size=2;using(var updater=new SelfUpdater(new BinaryReply(new byte[]{1,2},null)))Reject(()=>updater.Download(download,root,null,CancellationToken.None).GetAwaiter().GetResult(),"download checksum failure");using(var updater=new SelfUpdater(new BinaryReply(new byte[]{1,2},"https://example.com/untrusted.zip")))Reject(()=>updater.Download(download,root,null,CancellationToken.None).GetAwaiter().GetResult(),"foreign redirect server rejected");Check(!Directory.GetDirectories(SelfUpdater.JobsRoot).Any(d=>File.Exists(Path.Combine(d,"download.zip"))),"failed downloads cleaned up");
        return count;
      }finally{SelfUpdater.TestJobsRoot=null;}
    }
    class RateLimited:HttpMessageHandler {readonly string manifest;public RateLimited(string value){manifest=value;}protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){if(request.RequestUri.Host=="api.github.com")return Task.FromResult(new HttpResponseMessage((HttpStatusCode)403){Content=new StringContent("rate limit exceeded"),RequestMessage=request});if(manifest==null||!request.RequestUri.AbsolutePath.EndsWith("/releases/latest/download/nexus-update.json"))return Task.FromResult(new HttpResponseMessage(HttpStatusCode.NotFound){RequestMessage=request});return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(manifest),RequestMessage=request});}}
    class Reply:HttpMessageHandler {readonly string body;public Reply(string value){body=value;}protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){token.ThrowIfCancellationRequested();return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(body),RequestMessage=request});}}
    class BinaryReply:HttpMessageHandler {readonly byte[] body;readonly string redirect;public BinaryReply(byte[] value,string url){body=value;redirect=url;}protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){token.ThrowIfCancellationRequested();return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(body),RequestMessage=redirect==null?request:new HttpRequestMessage(HttpMethod.Get,redirect)});}}
  }
}
